modelica_source:
model Baseline
  extends Modelica.Mechanics.Translational.Examples.WhyArrows;
end Baseline;
model BUG017
  extends Modelica.Mechanics.Translational.Examples.WhyArrows(inertia2(m=0));
end BUG017;
model FinalBUG017
  extends Modelica.Mechanics.Translational.Examples.WhyArrows(inertia2(final m=0));
end FinalBUG017;

mos:
setCommandLineOptions("--numProcs=1 --evaluateFinalParameters=true");
setCompiler("gcc");
setCXXCompiler("g++");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/Modelica/package.mo");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/ModelicaTest/package.mo");
loadFile("Cases.mo");
getErrorString();
print("AUDIT_CASE Baseline\n");
simulate(Baseline, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE BUG017\n");
simulate(BUG017, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalBUG017\n");
simulate(FinalBUG017, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_OVERRIDE BUG017\n");
system("./Baseline -override inertia2.m=0 -r=BUG017_override.csv");
